// Vintage / Lo-Fi Voicer: Suno Studio audio effect (applied to rendered audio, not a lyric tag).
// Signal chain, in order:
//   1. Input trim: convert 'input gain' dB to linear and scale each channel.
//   2. Tilt EQ: two shelving g.biquad stages driven by one 'tilt' param. Lowshelf uses +tilt near 200Hz;
//      highshelf uses -tilt near 5kHz (opposite directions via g.mul by -1).
//   3. Tape saturation: scale by 'drive' (dB via g.dbToLin) then g.tanh for soft tape-style clipping.
//   4. Band-limited squeeze: g.biquad highpass at 'lowCut' then g.biquad lowpass at 'highCut'.
//   5. Dry/wet: g.lerp between trimmed dry and processed by 'dry/wet mix'.
//   6. Output gain, bypass select via g.lerp, then g.tanh safety before g.output.
function build(g, config) {
  var inL = g.input('audioInL');
  var inR = g.input('audioInR');

  var inGainDb = g.input('input gain');
  var tiltDb = g.input('tilt');
  var driveDb = g.input('drive');
  var lowCut = g.input('lowCut');
  var highCut = g.input('highCut');
  var mixPct = g.input('dry/wet mix');
  var outGainDb = g.input('output gain');
  var bypass = g.input('bypass');

  var inGain = g.dbToLin(inGainDb);
  var outGain = g.dbToLin(outGainDb);
  var driveLin = g.dbToLin(driveDb);
  var mix = g.clamp(g.div(mixPct, g.constant(100)), g.zero(), g.constant(1));
  var negTilt = g.mul(tiltDb, g.constant(-1));

  function chain(x) {
    var trimmed = g.mul(x, inGain);
    var low = g.biquad({ input: trimmed, cutoff: g.constant(200), resonance: g.constant(0.707), mode: 'lowshelf', gainDb: tiltDb });
    var tilted = g.biquad({ input: low, cutoff: g.constant(5000), resonance: g.constant(0.707), mode: 'highshelf', gainDb: negTilt });
    var sat = g.tanh(g.mul(tilted, driveLin));
    var hp = g.biquad({ input: sat, cutoff: lowCut, resonance: g.constant(0.707), mode: 'highpass' });
    var lp = g.biquad({ input: hp, cutoff: highCut, resonance: g.constant(0.707), mode: 'lowpass' });
    var wet = g.lerp(mix, trimmed, lp);
    var out = g.mul(wet, outGain);
    var active = g.lerp(bypass, out, trimmed);
    return g.tanh(active);
  }

  g.output('audioOutL', chain(inL));
  g.output('audioOutR', chain(inR));
}
